<script setup>
import { Link, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
defineProps({skins:Object});
const status = ref('all');
const search = ref('');
const importOpen = ref(false);
const bundle = useForm({ bundle_files: [], relative_paths: [] });
const selectBundle = event => { const files = Array.from(event.target.files || []); bundle.bundle_files = files; bundle.relative_paths = files.map(file => file.webkitRelativePath || file.name); };
const uploadBundle = () => bundle.post(route('admin.profile-skins.import-bundle'), { forceFormData: true });
</script>
<template><AssessmentLayout title="Profile skin armory" subtitle="Satu folder = satu skin. Import bundle, sinkronisasi contoh, dan kelola metadata." breadcrumb="Toko & personalisasi"><template #action><button class="primary" type="button" @click="importOpen=!importOpen">Import bundle</button></template><form v-if="importOpen" class="panel" style="margin-bottom:20px" @submit.prevent="uploadBundle"><h2>Import folder skin</h2><p class="muted">Pilih folder yang berisi skin.json beserta asetnya.</p><input type="file" webkitdirectory multiple @change="selectBundle" /><span class="error">{{ bundle.errors.bundle_files }}</span><div class="actions"><button class="primary" :disabled="bundle.processing || bundle.bundle_files.length<2">Import {{ bundle.bundle_files.length }} file</button></div></form><div class="tabs"><button v-for="entry in [['all','Semua'],['active','Aktif'],['inactive','Draft']]" :key="entry[0]" type="button" class="secondary" :aria-pressed="status===entry[0]" @click="status=entry[0]">{{ entry[1] }}</button></div><div class="filters"><input v-model="search" placeholder="Cari nama skin" aria-label="Cari skin" /><Link class="secondary" :href="route('redesign.profile-skins.create')">Tambah manual</Link></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px"><article v-for="skin in skins.data.filter(item=>(status==='all'||(status==='active')===!!item.is_active)&&item.name.toLowerCase().includes(search.toLowerCase()))" :key="skin.id" class="panel"><img v-if="skin.preview_image_path" :src="'/storage/'+skin.preview_image_path" :alt="skin.name" style="width:60px;height:60px;object-fit:cover;border-radius:9px" /><div v-else style="width:60px;height:60px;display:grid;place-items:center;background:#e3dcf7;color:#00857c;border-radius:9px;font-weight:800">SK</div><h2 style="margin-top:22px">{{ skin.name }}</h2><p class="muted">{{ skin.shop_item?.price_gold || 0 }} gold · {{ skin.bundle_root_path ? 'Bundle siap dipakai' : 'Konfigurasi manual' }}</p><p>{{ skin.is_active?'Aktif':'Draft' }}</p><hr style="border:0;border-top:1px solid #dce6e8;margin:20px 0" /><Link :href="route('redesign.profile-skins.edit',skin.id)">Buka detail →</Link></article></div><div class="pager"><Link v-for="(link,index) in skins.links" :key="index" :href="link.url||'#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></AssessmentLayout></template>
